def evaluate(tokens):
    stack=[]
    for token in tokens.split():
        if token.lstrip("-").isdigit():
            stack.append(int(token))
        else:
            b=stack.pop()
            a=stack.pop()
            stack.append(a+b if token=="+" else a-b if token=="-" else a*b)
    return stack[-1]
